const generateAuditEntries = (): AuditEntry[] => {
  const entries: AuditEntry[] = [];
  const actions = [
    { action: 'Use case submitted', target: 'UC-008', details: 'Gas Flaring Reduction Advisor submitted for IDT review', actor: 'David Chen', persona: 'Business Sponsor' },
    { action: 'Status changed', target: 'UC-001', details: 'Status updated from approved to in-development', actor: 'Purnima Girish', persona: 'IDE GM' },
    { action: 'Approval granted', target: 'UC-001', details: 'IDT Qualification approved with comments', actor: 'Anika Patel', persona: 'IDT Advisor' },
    { action: 'Model deployed', target: 'EP-001', details: 'Regulatory Compliance Report Generator deployed to Production', actor: 'Marcus Johnson', persona: 'IDE PM' },
    { action: 'Alert acknowledged', target: 'ALT-002', details: 'Response time SLA breach acknowledged', actor: 'Elena Vasquez', persona: 'IDSO GM' },
    { action: 'Pod assigned', target: 'UC-004', details: 'Predictive Equipment Failure assigned to Alpha Pod', actor: 'Purnima Girish', persona: 'IDE GM' },
    { action: 'Persona switched', target: 'System', details: 'Switched from IDE GM to IDT Advisor view', actor: 'Purnima Girish', persona: 'IDE GM' },
    { action: 'Data ingestion completed', target: 'DS-001', details: 'Well Telemetry Stream — 84,231 records processed', actor: 'System', persona: 'System' },
    { action: 'Experiment started', target: 'EXP-003', details: 'XGBoost training initiated for Contract Anomaly Detection', actor: 'Arjun Das', persona: 'Pod Member' },
    { action: 'Use case rejected', target: 'UC-013', details: 'Rejected: Insufficient data availability for proposed solution', actor: 'Robert van der Berg', persona: 'IDT GM' },
    { action: 'Approval requested', target: 'UC-005', details: 'Supply Chain Carbon Emission Tracker submitted for IDT qualification', actor: 'Anika Patel', persona: 'IDT Advisor' },
    { action: 'Sprint completed', target: 'POD-001', details: 'Alpha Pod Sprint 2 completed — 32/34 story points', actor: 'Rajesh Kumar', persona: 'Wipro Delivery' },
    { action: 'Component updated', target: 'COMP-001', details: 'RAG Pipeline Template upgraded to v3.2.1', actor: 'Vikram Sharma', persona: 'Pod Member' },
    { action: 'Risk assessment updated', target: 'UC-003', details: 'Risk level changed from medium to high — cross-system dependencies identified', actor: 'Anika Patel', persona: 'IDT Advisor' },
    { action: 'Model promoted', target: 'EXP-001', details: 'LSTM v1.2 promoted for deployment — accuracy 94.2%', actor: 'Marcus Johnson', persona: 'IDE PM' },
    { action: 'Use case submitted', target: 'UC-012', details: 'LNG Demand Forecasting Engine submitted', actor: 'David Chen', persona: 'Business Sponsor' },
    { action: 'Architecture review completed', target: 'UC-006', details: 'Drilling Operations Optimization — architecture approved with conditions', actor: 'Marcus Johnson', persona: 'IDE PM' },
    { action: 'Training milestone completed', target: 'Build-to-Transfer', details: 'Shell architects trained on factory patterns', actor: 'Purnima Girish', persona: 'IDE GM' },
    { action: 'SLA breach detected', target: 'EP-003', details: 'Response time exceeded 500ms threshold', actor: 'System', persona: 'System' },
    { action: 'Data quality alert', target: 'DS-001', details: 'Null rate spike in pressure_psi field — 2.3% (threshold: 1%)', actor: 'System', persona: 'System' },
  ];

  const baseDate = new Date('2026-03-01');
  for (let i = 0; i < 55; i++) {
    const actionTemplate = actions[i % actions.length];
    const dayOffset = Math.floor(i * 0.55);
    const entryDate = new Date(baseDate);
    entryDate.setDate(entryDate.getDate() + dayOffset);
    entryDate.setHours(8 + Math.floor(Math.random() * 10), Math.floor(Math.random() * 60));
    entries.push({
      id: `AUD-${String(i + 1).padStart(3, '0')}`,
      timestamp: entryDate.toISOString(),
      actor: actionTemplate.actor,
      persona: actionTemplate.persona,
      action: actionTemplate.action,
      target: actionTemplate.target,
      details: actionTemplate.details,
      ip: `10.${Math.floor(Math.random() * 255)}.${Math.floor(Math.random() * 255)}.***`,
    });
  }
  return entries.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
};

export const auditLog: AuditEntry[] = generateAuditEntries();
